1	package com.example.starter.translation.repo;
2	
3	import com.example.starter.translation.domain.Rows.ApprovalRow;
4	import com.example.starter.translation.domain.Rows.DocumentRow;
5	import com.example.starter.translation.domain.Rows.RequestLogRow;
6	import com.example.starter.translation.domain.Rows.SegmentRow;
7	import com.example.starter.translation.domain.Rows.TermRuleRow;
8	import com.example.starter.translation.domain.Rows.TranslationRow;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.jdbc.core.RowMapper;
11	import org.springframework.jdbc.support.GeneratedKeyHolder;
12	import org.springframework.jdbc.support.KeyHolder;
13	import org.springframework.stereotype.Repository;
14	
15	import java.sql.PreparedStatement;
16	import java.util.Arrays;
17	import java.util.List;
18	import java.util.Optional;
19	
20	/**
21	 * 多语种段落发布的数据访问层，基于 JdbcTemplate 与参数化 SQL。
22	 * 目标语言在 document 表中以逗号分隔存储，行记录中还原为列表。
23	 */
24	@Repository
25	public class TranslationRepository {
26	
27	    private static final RowMapper<DocumentRow> DOCUMENT_MAPPER = (rs, n) -> new DocumentRow(
28	            rs.getLong("document_id"),
29	            Arrays.stream(rs.getString("target_languages").split(",")).toList(),
30	            rs.getInt("draft_version"),
31	            rs.getInt("published_version"),
32	            rs.getInt("term_version"));
33	
34	    private static final RowMapper<SegmentRow> SEGMENT_MAPPER = (rs, n) -> new SegmentRow(
35	            rs.getString("segment_id"), rs.getString("source_text"), rs.getInt("source_version"));
36	
37	    private static final RowMapper<TranslationRow> TRANSLATION_MAPPER = (rs, n) -> new TranslationRow(
38	            rs.getString("segment_id"), rs.getString("language"), rs.getString("content"),
39	            rs.getString("author"), rs.getInt("source_version"), rs.getInt("translation_version"),
40	            rs.getInt("term_version"));
41	
42	    private static final RowMapper<ApprovalRow> APPROVAL_MAPPER = (rs, n) -> new ApprovalRow(
43	            rs.getString("segment_id"), rs.getString("language"), rs.getString("reviewer"),
44	            rs.getInt("source_version"), rs.getInt("translation_version"));
45	
46	    private static final RowMapper<TermRuleRow> TERM_RULE_MAPPER = (rs, n) -> new TermRuleRow(
47	            rs.getString("source_term"), rs.getString("language"), rs.getString("required_translation"));
48	
49	    private final JdbcTemplate jdbc;
50	
51	    public TranslationRepository(JdbcTemplate jdbc) {
52	        this.jdbc = jdbc;
53	    }
54	
55	    /** 插入文档并返回自增 ID，初始草稿版本 1、发布版本 0、术语版本 0。 */
56	    public long insertDocument(List<String> targetLanguages) {
57	        KeyHolder keyHolder = new GeneratedKeyHolder();
58	        jdbc.update(con -> {
59	            PreparedStatement ps = con.prepareStatement(
60	                    "INSERT INTO document (target_languages, draft_version, published_version, term_version) "
61	                            + "VALUES (?, 1, 0, 0)",
62	                    new String[]{"document_id"});
63	            ps.setString(1, String.join(",", targetLanguages));
64	            return ps;
65	        }, keyHolder);
66	        Number key = keyHolder.getKey();
67	        if (key == null) {
68	            throw new IllegalStateException("文档创建后未返回自增主键");
69	        }
70	        return key.longValue();
71	    }
72	
73	    /** 按 ID 查询文档并加行级写锁（FOR UPDATE），用于串行化同一文档的写操作。 */
74	    public Optional<DocumentRow> findDocumentForUpdate(long documentId) {
75	        List<DocumentRow> rows = jdbc.query(
76	                "SELECT document_id, target_languages, draft_version, published_version, term_version "
77	                        + "FROM document WHERE document_id = ? FOR UPDATE",
78	                DOCUMENT_MAPPER, documentId);
79	        return rows.stream().findFirst();
80	    }
81	
82	    /** 只读查询文档（不加锁），用于快照查询。 */
83	    public Optional<DocumentRow> findDocument(long documentId) {
84	        List<DocumentRow> rows = jdbc.query(
85	                "SELECT document_id, target_languages, draft_version, published_version, term_version "
86	                        + "FROM document WHERE document_id = ?",
87	                DOCUMENT_MAPPER, documentId);
88	        return rows.stream().findFirst();
89	    }
90	
91	    public void updateDraftVersion(long documentId, int draftVersion) {
92	        jdbc.update("UPDATE document SET draft_version = ? WHERE document_id = ?", draftVersion, documentId);
93	    }
94	
95	    public void updatePublishedVersion(long documentId, int publishedVersion) {
96	        jdbc.update("UPDATE document SET published_version = ? WHERE document_id = ?", publishedVersion, documentId);
97	    }
98	
99	    public void updateTermVersion(long documentId, int termVersion) {
100	        jdbc.update("UPDATE document SET term_version = ? WHERE document_id = ?", termVersion, documentId);
101	    }
102	
103	    public void insertSegment(long documentId, String segmentId, String sourceText) {
104	        jdbc.update("INSERT INTO segment (document_id, segment_id, source_text, source_version) VALUES (?, ?, ?, 1)",
105	                documentId, segmentId, sourceText);
106	    }
107	
108	    public Optional<SegmentRow> findSegment(long documentId, String segmentId) {
109	        List<SegmentRow> rows = jdbc.query(
110	                "SELECT segment_id, source_text, source_version FROM segment "
111	                        + "WHERE document_id = ? AND segment_id = ?",
112	                SEGMENT_MAPPER, documentId, segmentId);
113	        return rows.stream().findFirst();
114	    }
115	
116	    public List<SegmentRow> listSegments(long documentId) {
117	        return jdbc.query(
118	                "SELECT segment_id, source_text, source_version FROM segment "
119	                        + "WHERE document_id = ? ORDER BY segment_id",
120	                SEGMENT_MAPPER, documentId);
121	    }
122	
123	    public void updateSegmentSource(long documentId, String segmentId, String sourceText, int sourceVersion) {
124	        jdbc.update("UPDATE segment SET source_text = ?, source_version = ? "
125	                        + "WHERE document_id = ? AND segment_id = ?",
126	                sourceText, sourceVersion, documentId, segmentId);
127	    }
128	
129	    public Optional<TranslationRow> findTranslation(long documentId, String segmentId, String language) {
130	        List<TranslationRow> rows = jdbc.query(
131	                "SELECT segment_id, language, content, author, source_version, translation_version, term_version "
132	                        + "FROM translation WHERE document_id = ? AND segment_id = ? AND language = ?",
133	                TRANSLATION_MAPPER, documentId, segmentId, language);
134	        return rows.stream().findFirst();
135	    }
136	
137	    public List<TranslationRow> listTranslations(long documentId) {
138	        return jdbc.query(
139	                "SELECT segment_id, language, content, author, source_version, translation_version, term_version "
140	                        + "FROM translation WHERE document_id = ? ORDER BY segment_id, language",
141	                TRANSLATION_MAPPER, documentId);
142	    }
143	
144	    /** 插入或覆盖译文（按主键段落+语言唯一）。 */
145	    public void upsertTranslation(long documentId, TranslationRow row) {
146	        int updated = jdbc.update(
147	                "UPDATE translation SET content = ?, author = ?, source_version = ?, translation_version = ?, "
148	                        + "term_version = ?, updated_at = CURRENT_TIMESTAMP "
149	                        + "WHERE document_id = ? AND segment_id = ? AND language = ?",
150	                row.content(), row.author(), row.sourceVersion(), row.translationVersion(), row.termVersion(),
151	                documentId, row.segmentId(), row.language());
152	        if (updated == 0) {
153	            jdbc.update("INSERT INTO translation (document_id, segment_id, language, content, author, "
154	                            + "source_version, translation_version, term_version) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
155	                    documentId, row.segmentId(), row.language(), row.content(), row.author(),
156	                    row.sourceVersion(), row.translationVersion(), row.termVersion());
157	        }
158	    }
159	
160	    public Optional<ApprovalRow> findApproval(long documentId, String segmentId, String language) {
161	        List<ApprovalRow> rows = jdbc.query(
162	                "SELECT segment_id, language, reviewer, source_version, translation_version "
163	                        + "FROM approval WHERE document_id = ? AND segment_id = ? AND language = ?",
164	                APPROVAL_MAPPER, documentId, segmentId, language);
165	        return rows.stream().findFirst();
166	    }
167	
168	    public List<ApprovalRow> listApprovals(long documentId) {
169	        return jdbc.query(
170	                "SELECT segment_id, language, reviewer, source_version, translation_version "
171	                        + "FROM approval WHERE document_id = ? ORDER BY segment_id, language",
172	                APPROVAL_MAPPER, documentId);
173	    }
174	
175	    /** 插入或覆盖批准（按主键段落+语言唯一）。 */
176	    public void upsertApproval(long documentId, ApprovalRow row) {
177	        int updated = jdbc.update(
178	                "UPDATE approval SET reviewer = ?, source_version = ?, translation_version = ?, "
179	                        + "approved_at = CURRENT_TIMESTAMP "
180	                        + "WHERE document_id = ? AND segment_id = ? AND language = ?",
181	                row.reviewer(), row.sourceVersion(), row.translationVersion(),
182	                documentId, row.segmentId(), row.language());
183	        if (updated == 0) {
184	            jdbc.update("INSERT INTO approval (document_id, segment_id, language, reviewer, "
185	                            + "source_version, translation_version) VALUES (?, ?, ?, ?, ?, ?)",
186	                    documentId, row.segmentId(), row.language(), row.reviewer(),
187	                    row.sourceVersion(), row.translationVersion());
188	        }
189	    }
190	
191	    public void insertSnapshot(long documentId, int publishedVersion, String snapshotJson) {
192	        jdbc.update("INSERT INTO release_snapshot (document_id, published_version, snapshot_json) VALUES (?, ?, ?)",
193	                documentId, publishedVersion, snapshotJson);
194	    }
195	
196	    /** 插入术语版本主记录（不可变，主键已存在时抛冲突）。 */
197	    public void insertTermVersion(long documentId, int termVersion) {
198	        jdbc.update("INSERT INTO term_version (document_id, term_version) VALUES (?, ?)",
199	                documentId, termVersion);
200	    }
201	
202	    /** 插入一条术语规则，归属指定术语版本。 */
203	    public void insertTermRule(long documentId, int termVersion, TermRuleRow rule) {
204	        jdbc.update("INSERT INTO term_rule (document_id, term_version, source_term, language, "
205	                        + "required_translation) VALUES (?, ?, ?, ?, ?)",
206	                documentId, termVersion, rule.sourceTerm(), rule.language(), rule.requiredTranslation());
207	    }
