1	package com.example.starter.translation;
2	
3	import org.junit.jupiter.api.DisplayName;
4	import org.junit.jupiter.api.Test;
5	
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.concurrent.CountDownLatch;
9	import java.util.concurrent.ExecutorService;
10	import java.util.concurrent.Executors;
11	import java.util.concurrent.Future;
12	import java.util.concurrent.TimeUnit;
13	
14	import static org.assertj.core.api.Assertions.assertThat;
15	
16	/**
17	 * 并发与幂等边界测试：真实并发调用，通过门闩协调同时发起，设置超时并断言最终数据状态。
18	 */
19	class ConcurrencyTest extends AbstractIntegrationTest {
20	
21	    @Test
22	    @DisplayName("并发提交译文：同一文档多个段落并发提交全部成功，草稿版本无丢失更新")
23	    void concurrentTranslationSubmits() throws Exception {
24	        StringBuilder segments = new StringBuilder("[");
25	        int segmentCount = 6;
26	        for (int i = 1; i <= segmentCount; i++) {
27	            if (i > 1) {
28	                segments.append(',');
29	            }
30	            segments.append("{\"segmentId\":\"s").append(i).append("\",\"sourceText\":\"原文").append(i)
31	                    .append("\"}");
32	        }
33	        segments.append(']');
34	        long docId = createDocument(newRequestId(), "[\"en\"]", segments.toString());
35	
36	        ExecutorService pool = Executors.newFixedThreadPool(segmentCount);
37	        CountDownLatch gate = new CountDownLatch(1);
38	        List<Future<ApiResult>> futures = new ArrayList<>();
39	        for (int i = 1; i <= segmentCount; i++) {
40	            final String segmentId = "s" + i;
41	            futures.add(pool.submit(() -> {
42	                gate.await();
43	                return submitTranslation(docId, segmentId, "en", "alice", "译文-" + segmentId, 1,
44	                        newRequestId());
45	            }));
46	        }
47	        gate.countDown();
48	        for (Future<ApiResult> future : futures) {
49	            assertThat(future.get(30, TimeUnit.SECONDS).status()).isEqualTo(200);
50	        }
51	        pool.shutdown();
52	
53	        Integer draftVersion = jdbc.queryForObject(
54	                "SELECT draft_version FROM document WHERE document_id = ?", Integer.class, docId);
55	        assertThat(draftVersion).isEqualTo(1 + segmentCount);
56	        Integer translations = jdbc.queryForObject(
57	                "SELECT COUNT(*) FROM translation WHERE document_id = ?", Integer.class, docId);
58	        assertThat(translations).isEqualTo(segmentCount);
59	    }
60	
61	    @Test
62	    @DisplayName("并发同 requestId 同参：仅执行一次，全部重放同一成功结果")
63	    void concurrentSameRequestId() throws Exception {
64	        String requestId = newRequestId();
65	        String body = "{\"requestId\":\"" + requestId + "\",\"targetLanguages\":[\"en\"],"
66	                + "\"segments\":[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]}";
67	        int threads = 8;
68	        ExecutorService pool = Executors.newFixedThreadPool(threads);
69	        CountDownLatch gate = new CountDownLatch(1);
70	        List<Future<ApiResult>> futures = new ArrayList<>();
71	        for (int i = 0; i < threads; i++) {
72	            futures.add(pool.submit(() -> {
73	                gate.await();
74	                return postJson("/api/documents", body);
75	            }));
76	        }
77	        gate.countDown();
78	        List<ApiResult> results = new ArrayList<>();
79	        for (Future<ApiResult> future : futures) {
80	            results.add(future.get(30, TimeUnit.SECONDS));
81	        }
82	        pool.shutdown();
83	
84	        long documentId = results.get(0).body().get("documentId").asLong();
85	        for (ApiResult result : results) {
86	            assertThat(result.status()).isEqualTo(201);
87	            assertThat(result.body().get("documentId").asLong()).isEqualTo(documentId);
88	        }
89	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM document", Integer.class)).isEqualTo(1);
90	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM request_log", Integer.class)).isEqualTo(1);
91	    }
92	
93	    @Test
94	    @DisplayName("发布与源文修订并发：对应一个一致状态，失败不产生部分快照")
95	    void concurrentPublishAndRevise() throws Exception {
96	        long docId = createDocument(newRequestId(), "[\"en\"]",
97	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
98	        submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
99	        approve(docId, "s1", "en", "bob", 1, newRequestId());
100	        // 当前草稿版本 2、发布版本 0
101	
102	        ExecutorService pool = Executors.newFixedThreadPool(2);
103	        CountDownLatch gate = new CountDownLatch(1);
104	        Future<ApiResult> publishFuture = pool.submit(() -> {
105	            gate.await();
106	            return publish(docId, 2, 0, newRequestId());
107	        });
108	        Future<ApiResult> reviseFuture = pool.submit(() -> {
109	            gate.await();
110	            return putJson("/api/documents/" + docId + "/segments/s1/source",
111	                    "{\"requestId\":\"" + newRequestId() + "\",\"sourceText\":\"修订后原文\"}");
112	        });
113	        gate.countDown();
114	        ApiResult publishResult = publishFuture.get(30, TimeUnit.SECONDS);
115	        ApiResult reviseResult = reviseFuture.get(30, TimeUnit.SECONDS);
116	        pool.shutdown();
117	
118	        assertThat(reviseResult.status()).isEqualTo(200);
119	        assertThat(publishResult.status()).isIn(201, 409);
120	
121	        Integer draftVersion = jdbc.queryForObject(
122	                "SELECT draft_version FROM document WHERE document_id = ?", Integer.class, docId);
123	        Integer publishedVersion = jdbc.queryForObject(
124	                "SELECT published_version FROM document WHERE document_id = ?", Integer.class, docId);
125	        Integer snapshots = jdbc.queryForObject(
126	                "SELECT COUNT(*) FROM release_snapshot WHERE document_id = ?", Integer.class, docId);
127	
128	        // 修订必然成功并使草稿版本加一；发布版本与快照数量必须一致（无部分快照）
129	        assertThat(draftVersion).isEqualTo(3);
130	        assertThat(snapshots).isEqualTo(publishedVersion);
131	        if (publishResult.status() == 201) {
132	            // 发布先于修订：发布版本 1，快照中为修订前源文
133	            assertThat(publishedVersion).isEqualTo(1);
134	            ApiResult release = getJson("/api/documents/" + docId + "/releases/1");
135	            assertThat(release.status()).isEqualTo(200);
136	            assertThat(release.body().get("segments").get(0).get("sourceText").asText()).isEqualTo("原文");
137	        } else {
138	            // 修订先于发布：期望草稿版本不符，发布 409 且无快照
139	            assertThat(publishedVersion).isZero();
140	        }
141	    }
142	
